/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var result = api.data.get_comm_task_channel_details.output.data;
    var availableChannels = api.state.availableChannels;
    availableChannels.email = result.hasOwnProperty("email");
    availableChannels.slack = result.hasOwnProperty("slack");
    availableChannels.slackNotification = result.hasOwnProperty("slack-message");
    availableChannels.teams = result.hasOwnProperty("ms-teams-message");
    availableChannels.sms = result.hasOwnProperty("sms");
    return {
        propName: "availableChannels",
        value: availableChannels
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const channelCollapseStateMap = {
        "email": "isEmailCollapsed",
        "slack": "isSlackChannelCollapsed",
        "slack-message": "isSlackNotificationCollapsed",
        "ms-teams-message": "isTeamsCollapsed",
        "sms": "isSMSCollapsed",
        "dex_desktop_assistant": "isDexCollapsed"
    };
    var result = api.data.get_comm_task_channel_details.output.data;
    for (let channel in channelCollapseStateMap) {
        if (result.hasOwnProperty(channel))
            return {
                propName: channelCollapseStateMap[channel],
                value: false
            };
    }
}

